TYPO03_agentic_grep_381d9b69.final_sparql:
PREFIX oriont: <https://orienting.eu/oriont#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?activity ?activityLabel ?flow ?flowType
WHERE {
  ?activity a oriont:Activity .
  OPTIONAL { ?activity rdfs:label ?activityLabel . }

  {
    ?flow a oriont:Flow .
    ?flow oriont:isInputOf ?activity .
    BIND("input" AS ?flowType)
  }
  UNION
  {
    ?flow a oriont:Flow .
    ?flow oriont:isOutputOf ?activity .
    BIND("output" AS ?flowType)
  }
}
ORDER BY ?activity ?flowType ?flow
LIMIT 100

